import{z as l,x as s,o as B,c as n,q as e,j as o,D as E,d as t,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"DBO 对 IBO","description":"","frontmatter":{"title":"DBO 对 IBO","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dbo-ibo.md","filePath":"litho/dbo-ibo.md","lastUpdated":1791063341000}'),D={name:"litho/dbo-ibo.md"};function p(d,a,O,h,C,_){const A=s("Mermaid");return B(),n("div",null,[a[2]||(a[2]=e('<h1 id="dbo-对-ibo" tabindex="-1">DBO 对 IBO <a class="header-anchor" href="#dbo-对-ibo" aria-label="Permalink to &quot;DBO 对 IBO&quot;">​</a></h1><div class="epigraph"><p>成像式套刻看盒子的中心；衍射式套刻看叠栅左右级的不平衡。量的都是标记位移，怕的工艺不对称却不是同一类。</p><footer>—— 据 ASML 对衍射套刻（YieldStar 一类）与成像套刻的公开对比整理</footer></div><p><a href="/litho/overlay-marks">上一课</a>已经点名成像式（IBO）与衍射式（DBO），并警告工艺不对称会假扮 overlay。缺口是产线怎么选：对比、吞吐、对 CMP/刻蚀风的敏感、以及能不能加密到够拟合芯片内残差。本课把两者对打。高阶校正项怎么吃这些读数，留给<a href="/litho/high-order-overlay">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IBO 用显微镜看盒中盒或条中条的中心差，光学分辨率和算法阈值限制噪声；膜层一暗，对比垮，要换色或换结构。DBO 用两层叠栅，位移写成 ±1 级强度差或相位差，小位移线性灵敏，ASML 公开材料把这条路做成 YieldStar 的主干。缺口不是「衍射一定更先进」，而是：在这层薄膜与这套刻蚀风下，哪一种标记的不对称偏置更小、采样更快。</p><p>划片槽面积有限。IBO 标记往往更大、更吃对比；DBO 光栅可以做得密，便于一场多点。加密的是拟合，不是把标记做成晶体管。同一层若 IBO、DBO 混采，必须先做相关，再进 APC，否则高阶项会吃进两套尺子的差。</p><p>一条产线拿到具体的一层，怎么在 IBO 与 DBO 之间做选择？入口问题依次是：这一层膜下还能不能拍出清晰像、这层要喂多密的场内采样、以及当前的刻蚀与 CMP 风更少带偏哪把尺。</p>',7)),(B(),o(i,null,{default:E(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAY%5B%22%E6%9C%AC%E5%B1%82%EF%BC%9A%E8%96%84%E8%86%9C%E6%A0%88%20%2F%20%E5%85%B3%E9%94%AE%E5%BA%A6%20%2F%20%E5%88%92%E7%89%87%E6%A7%BD%E9%9D%A2%E7%A7%AF%22%5D%20--%3E%20Q1%7B%22%E6%88%90%E5%83%8F%E5%AF%B9%E6%AF%94%E5%A4%9F%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22%E5%8E%9A%E8%86%9C%E9%AB%98%E5%AF%B9%E6%AF%94%22%7C%20A1%5B%22IBO%20%E5%8F%AF%E7%94%A8%EF%BC%8C%E5%8E%86%E5%8F%B2%E9%85%8D%E6%96%B9%E6%88%90%E7%86%9F%22%5D%0A%20%20Q1%20--%3E%7C%22%E8%86%9C%E6%9A%97%E5%AF%B9%E6%AF%94%E5%B7%AE%22%7C%20Q2%7B%22%E8%A6%81%E5%9C%BA%E5%86%85%E9%AB%98%E5%AF%86%E5%BA%A6%E9%87%87%E6%A0%B7%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E8%A6%81%E5%96%82%E9%AB%98%E9%98%B6%E6%A8%A1%E5%9E%8B%22%7C%20A2%5B%22DBO%EF%BC%9A%E6%A0%85%E5%AF%86%E3%80%81%E5%8D%95%E7%82%B9%E5%BF%AB%E3%80%81%E6%98%93%E5%8A%A0%E5%AF%86%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E9%9C%80%E8%A6%81%22%7C%20A3%5B%22%E6%8D%A2%E8%89%B2%E6%88%96%E6%8D%A2%E6%A0%87%E8%AE%B0%E7%BB%93%E6%9E%84%E7%9A%84%20IBO%22%5D%0A%20%20A1%20--%3E%20CHK%5B%22%E5%AF%B9%E5%BD%93%E4%B8%8B%E5%B7%A5%E8%89%BA%E5%81%9A%E5%81%8F%E7%BD%AE%E7%9B%B8%E5%85%B3%22%5D%0A%20%20A2%20--%3E%20CHK%0A%20%20A3%20--%3E%20CHK%0A%20%20CHK%20--%3E%20APC%5B%22%E8%BF%9B%20APC%20%E5%89%8D%E9%94%81%E7%AE%97%E6%B3%95%E4%B8%8E%E6%BB%A4%E6%B3%A2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="光学套刻仍是代理" tabindex="-1">光学套刻仍是代理 <a class="header-anchor" href="#光学套刻仍是代理" aria-label="Permalink to &quot;光学套刻仍是代理&quot;">​</a></h3><p>无论 IBO 还是 DBO，读的都不是器件图形。电学套刻或专用电学垫才是最终。两种光学法都可以与电学差一截，差的来源不同：IBO 偏算法与低对比噪声，DBO 偏两层栅的形状差。选边是选偏置的可控性，不是选「更接近真值」的形而上学。</p><p><span class="marginnote">单机、匹配、产品套刻仍是三个数。DBO 换 IBO 改变的是产品上那个数怎么读，不改设备规格书里的工件台能力。</span></p><p><span class="marginnote">术语翻译：IBO（成像式套刻）就是「给上下两层各拍一张显微照片，量两个图形中心的错位」；DBO（衍射式套刻）是「把两层光栅叠在一起，看左右两个衍射级的强度差，从不平衡量反推位移」。一个量照片，一个量条纹，读的都是同一件事：层间错了几纳米。</span></p><p><span class="marginnote">直觉类比：IBO 像把两张透明胶片叠起来对图案，眼睛必须看清图形才能对准，图一暗就抓瞎；DBO 像看两片纱窗叠出的摩尔条纹——条纹挪一格就知道纱窗错位多少，不用看清单根纱线，所以光栅可以又密又小，方便一场里多测几百个点。</span></p><p><span class="marginnote">常见误区：初学者容易把 DBO 读数当成「真实套刻」。实际两种读数都会被工艺不对称带偏——刻蚀风让侧壁一边陡一边缓，成像质心和衍射质心搬家的方向与幅度还不同。所以光学读数只是代理，电学套刻才是最终裁判；混用两把尺前必须先做相关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IBO：选波长与焦面使内外图形同时清晰；多层金属后常要多色。对焦误差会把表观中心拉开，必须进测量配方。DBO：选叠栅周期让 ±1 级进计量光瞳；多波长减轻某一色上的不对称。ASML 公开口径是衍射套刻对某些工艺噪声更稳、适合高阶采样密度，而不是公布一条「所有层必须 DBO」的法令。</p><p>工艺不对称：刻蚀风让一侧侧壁斜，IBO 的实空间中心和 DBO 的衍射质心都会搬家，搬家量不同。缓解仍是标记设计、多波长、对称密度，不能靠把扫描机再拧一纳米消掉。上一课写过的原则，本课只强调：两种技术的残差对同一风的传递函数不同，相关要分开做。</p><p>换 CMP 或换硬掩模之后，相关要重做，不能把上一代的 DBO–IBO 偏置表接着用。</p><h3 id="与-cd-光栅的边界再钉一次" tabindex="-1">与 CD 光栅的边界再钉一次 <a class="header-anchor" href="#与-cd-光栅的边界再钉一次" aria-label="Permalink to &quot;与 CD 光栅的边界再钉一次&quot;">​</a></h3><p>OCD 垫反演剖面，DBO 反演位移，可以共用划片区域设计，不可共用拟合目标。穆勒矩阵看见的侧壁不对称，会进 DBO 偏置；那是工艺，要用刻蚀和标记设计收，不是换一套 IBO 算法就能假装没有。</p>',12)),(B(),o(i,null,{default:E(()=>[r(A,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20IBO%5B%22IBO%3A%20%E5%AE%9E%E7%A9%BA%E9%97%B4%E4%B8%AD%E5%BF%83%22%5D%20--%3E%20OL%5B%22%E6%A0%87%E8%AE%B0%E4%BD%8D%E7%A7%BB%22%5D%0A%20%20DBO%5B%22DBO%3A%20%E8%A1%8D%E5%B0%84%E7%BA%A7%E4%B8%8D%E5%B9%B3%E8%A1%A1%22%5D%20--%3E%20OL%0A%20%20WIND%5B%22%E5%88%BB%E8%9A%80%20%2F%20CMP%20%E4%B8%8D%E5%AF%B9%E7%A7%B0%22%5D%20--%3E%20IBO%0A%20%20WIND%20--%3E%20DBO%0A%20%20OL%20--%3E%20FIT%5B%22%E5%9C%BA%E5%86%85%E5%A4%9A%E7%82%B9%E6%8B%9F%E5%90%88%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>成像式把套刻写成像素质心差，受光学传递函数限制，对低空间频率的膜层起伏敏感。衍射式把套刻写成傅里叶差，对栅的占空比和侧壁同样敏感——那部分不是位移。多层膜的有效光学中心可以离开几何中心，于是「DBO 更稳」只在该栈的光学中心与电学中心够近时成立。换一层低 k 介质，结论可以翻面。</p><p>吞吐：DBO 的公开卖点包括较快的单点时间和因而更高的场内密度，供高阶模型吃。IBO 在某些厚膜、高对比层上仍然够用，且历史配方成熟。混跑时必须锁算法与滤波，否则匹配套刻里会混进计量差。</p><p><span class="marginnote">DBO 叠栅周期远大于器件节距，为的是让衍射级进计量光瞳。它不测量 \\(k_1\\) 极限线宽，只测量层间位移。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 YieldStar 的未公开精度表写成所有层的合同，也不把某种 IBO 商标开除出量产。LELE 的「第二次对第一次」要另定义标记层级，与前层金属那套盒不是自动同一物理。对准传感器（曝光前）与套刻计量（曝光后）仍是两条链，即使都用光栅家族。</p><p>后课默认：产品套刻读数来自 IBO 或 DBO 之一，且必须声明；高阶项吃的是这些读数的空间密度，不是换一种光学就会少几个多项式系数。</p><p><span class="marginnote">把 DBO–IBO 相关一次之后当永恒偏置，会在换 CMP 浆料时把整条 APC 带沟里。相关是工艺状态，要定期重做。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IBO 看中心，DBO 看衍射不平衡；都是标记位移的代理。</li><li>对同一刻蚀风，两种偏置传递函数不同，要分开校准。</li><li>DBO 便于加密采样，服务后课的高阶拟合；不是所有层的强制答案。</li><li>电学套刻仍是最终，光学再稳也是在线代理。</li><li>出处：ASML 对衍射套刻 / YieldStar 与成像套刻的公开说明；Levinson 对 overlay mark 的讨论。</li></ul>',10))])}const c=l(D,[["render",p]]);export{m as __pageData,c as default};
